import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation, useQueryClient } from 'react-query';
import { useForm } from 'react-hook-form';
import { createPrompt } from '../api/prompts';
import { FiPlus, FiX, FiSave, FiEye, FiEyeOff } from 'react-icons/fi';
import toast from 'react-hot-toast';

const CreatePrompt = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [tags, setTags] = useState([]);
  const [newTag, setNewTag] = useState('');
  const [isPublic, setIsPublic] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    watch,
  } = useForm();

  const content = watch('content', '');

  const createMutation = useMutation(createPrompt, {
    // onSuccess: (data) => {
    //   queryClient.invalidateQueries(['prompts']);
    //   toast.success('Prompt created successfully!');
    //   navigate(`/prompts/${data.prompt._id}`);
    // },
    // onError: (error) => {
    //   const message = error.response?.data?.message || 'Failed to create prompt';
    //   toast.error(message);
    // },
    onSuccess: (data) => {
  console.log('✅ Prompt creation response:', data);

  if (data?.prompt?._id) {
    queryClient.invalidateQueries(['prompts']);
    toast.success('Prompt created successfully!');
    navigate(`/prompts/${data.prompt._id}`);
  } else {
    toast.error('Unexpected server response. Prompt ID missing.');
  }
},

  });

  const handleAddTag = () => {
    const tag = newTag.trim().toLowerCase();
    if (tag && !tags.includes(tag) && tags.length < 10) {
      setTags([...tags, tag]);
      setNewTag('');
    }
  };

  const handleRemoveTag = (tagToRemove) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddTag();
    }
  };

  const onSubmit = async (data) => {
    setIsLoading(true);
    try {
      await createMutation.mutateAsync({
        ...data,
        tags,
        isPublic,
      });
    } finally {
      setIsLoading(false);
    }
  };

  const categories = [
    { value: 'chatgpt', label: 'ChatGPT' },
    { value: 'midjourney', label: 'Midjourney' },
    { value: 'dalle', label: 'DALL-E' },
    { value: 'bard', label: 'Bard' },
    { value: 'claude', label: 'Claude' },
    { value: 'other', label: 'Other' },
  ];

  return (
    <div className="max-w-4xl mx-auto">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Create New Prompt</h1>
        <p className="text-gray-600">Share your AI prompt with the community</p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Title */}
            <div>
              <label htmlFor="title" className="block text-sm font-medium text-gray-700 mb-2">
                Title *
              </label>
              <input
                type="text"
                id="title"
                {...register('title', {
                  required: 'Title is required',
                  maxLength: {
                    value: 100,
                    message: 'Title must be less than 100 characters',
                  },
                })}
                className={`input-field ${errors.title ? 'border-red-300' : ''}`}
                placeholder="Enter a descriptive title for your prompt"
              />
              {errors.title && (
                <p className="mt-1 text-sm text-red-600">{errors.title.message}</p>
              )}
            </div>

            {/* Content */}
            <div>
              <label htmlFor="content" className="block text-sm font-medium text-gray-700 mb-2">
                Prompt Content *
              </label>
              <textarea
                id="content"
                rows={8}
                {...register('content', {
                  required: 'Prompt content is required',
                  maxLength: {
                    value: 5000,
                    message: 'Content must be less than 5000 characters',
                  },
                })}
                className={`input-field resize-none ${errors.content ? 'border-red-300' : ''}`}
                placeholder="Enter your AI prompt here..."
              />
              {errors.content && (
                <p className="mt-1 text-sm text-red-600">{errors.content.message}</p>
              )}
              <div className="mt-1 text-sm text-gray-500">
                {content.length}/5000 characters
              </div>
            </div>

            {/* Description */}
            <div>
              <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-2">
                Description (Optional)
              </label>
              <textarea
                id="description"
                rows={3}
                {...register('description', {
                  maxLength: {
                    value: 500,
                    message: 'Description must be less than 500 characters',
                  },
                })}
                className={`input-field resize-none ${errors.description ? 'border-red-300' : ''}`}
                placeholder="Briefly describe what this prompt does..."
              />
              {errors.description && (
                <p className="mt-1 text-sm text-red-600">{errors.description.message}</p>
              )}
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Category */}
            <div>
              <label htmlFor="category" className="block text-sm font-medium text-gray-700 mb-2">
                Category
              </label>
              <select
                id="category"
                {...register('category')}
                className="input-field"
                defaultValue="other"
              >
                {categories.map((category) => (
                  <option key={category.value} value={category.value}>
                    {category.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Tags */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Tags (Optional)
              </label>
              <div className="space-y-2">
                <div className="flex">
                  <input
                    type="text"
                    value={newTag}
                    onChange={(e) => setNewTag(e.target.value)}
                    onKeyPress={handleKeyPress}
                    className="input-field rounded-r-none"
                    placeholder="Add a tag"
                    maxLength={20}
                  />
                  <button
                    type="button"
                    onClick={handleAddTag}
                    disabled={!newTag.trim() || tags.length >= 10}
                    className="px-4 py-2 bg-blue-600 text-white rounded-r-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  >
                    <FiPlus className="w-4 h-4" />
                  </button>
                </div>
                {tags.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {tags.map((tag, index) => (
                      <span
                        key={index}
                        className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800"
                      >
                        #{tag}
                        <button
                          type="button"
                          onClick={() => handleRemoveTag(tag)}
                          className="ml-1 hover:text-blue-600"
                        >
                          <FiX className="w-3 h-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                )}
                <p className="text-xs text-gray-500">
                  {tags.length}/10 tags • Press Enter to add
                </p>
              </div>
            </div>

            {/* Visibility */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Visibility
              </label>
              <div className="space-y-2">
                <label className="flex items-center">
                  <input
                    type="radio"
                    checked={isPublic}
                    onChange={() => setIsPublic(true)}
                    className="mr-2"
                  />
                  <span className="text-sm">Public - Anyone can see and use</span>
                </label>
                <label className="flex items-center">
                  <input
                    type="radio"
                    checked={!isPublic}
                    onChange={() => setIsPublic(false)}
                    className="mr-2"
                  />
                  <span className="text-sm">Private - Only you can see</span>
                </label>
              </div>
            </div>

            {/* Preview */}
            <div className="card">
              <h3 className="text-sm font-medium text-gray-700 mb-2">Preview</h3>
              <div className="text-sm text-gray-600 space-y-2">
                <p><strong>Title:</strong> {watch('title') || 'No title'}</p>
                <p><strong>Category:</strong> {categories.find(c => c.value === watch('category'))?.label || 'Other'}</p>
                <p><strong>Tags:</strong> {tags.length > 0 ? tags.map(tag => `#${tag}`).join(', ') : 'No tags'}</p>
                <p><strong>Visibility:</strong> {isPublic ? 'Public' : 'Private'}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Submit Button */}
        <div className="flex justify-end space-x-4 pt-6 border-t border-gray-200">
          <button
            type="button"
            onClick={() => navigate('/')}
            className="btn-secondary"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={isLoading}
            className="btn-primary flex items-center space-x-2"
          >
            {isLoading ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                <span>Creating...</span>
              </>
            ) : (
              <>
                <FiSave className="w-4 h-4" />
                <span>Create Prompt</span>
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CreatePrompt;
